function validate([nums, queries]) {
  const n = nums.length;
  if (n < 1 || n > 50000) return 'nums needs 1 to 50000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 0 || v > 1000000000)) return 'Each value in nums is an integer from 0 to 10^9.';
  if (queries.length < 1 || queries.length > 150000) return 'queries needs 1 to 150000 entries.';
  for (const query of queries) {
    if (!Array.isArray(query) || query.length !== 2) return 'Each query is a pair [x, y].';
    const [x, y] = query;
    if (!Number.isInteger(x) || x < 0 || x >= n) return 'Each x is an index of nums.';
    if (!Number.isInteger(y) || y < 1 || y > 50000) return 'Each y is between 1 and 50000.';
  }
  return null;
}

