function solve(nums, queries) {
  const MOD = 1000000007;
  const n = nums.length;
  const limit = Math.ceil(Math.sqrt(n));
  const suffix = new Map();
  const answer = [];

  for (const [start, step] of queries) {
    if (step <= limit) {
      if (!suffix.has(step)) {
        const sums = new Array(n).fill(0);
        for (let i = n - 1; i >= 0; i--) {
          const next = i + step < n ? sums[i + step] : 0;
          sums[i] = (nums[i] + next) % MOD;
        }
        suffix.set(step, sums);
      }
      answer.push(suffix.get(step)[start]);
    } else {
      let total = 0;
      for (let j = start; j < n; j += step) {
        total = (total + nums[j]) % MOD;
      }
      answer.push(total);
    }
  }
  return answer;
}

