  return queries.map(([x, y]) => {
    let total = 0n;
    for (let j = 0; j < nums.length; j++) {
      if (j >= x && (j - x) % y === 0) total += BigInt(nums[j]);
    }
    return Number(total % 1000000007n);
  });
