function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = 2000;
    const nums = Array.from({ length: n }, () => (rand() < 0.3 ? pick(999000000, 1000000000) : pick(0, 1000000000)));
    const queries = Array.from({ length: 2000 }, () => {
      const r = rand();
      const y = r < 0.5 ? pick(1, 50) : r < 0.9 ? pick(51, n) : pick(n + 1, 50000);
      return [pick(0, n - 1), y];
    });
    return [nums, queries];
  }
  const n = pick(1, 10);
  const big = rand() < 0.3;
  const nums = Array.from({ length: n }, () => (big ? pick(999999990, 1000000000) : pick(0, 20)));
  const q = pick(1, 8);
  const queries = Array.from({ length: q }, () => [pick(0, n - 1), rand() < 0.15 ? pick(1, 50000) : pick(1, n + 2)]);
  return [nums, queries];
}
